function pickText(msg) {
  if (!msg) return '';
  if (typeof msg === 'string') return msg;
  if (msg.text && typeof msg.text === 'string') return msg.text;
  if (msg.text && msg.text.body) return msg.text.body;
  if (msg.body) return msg.body;
  if (typeof msg.message === 'string') return msg.message;
  return '';
}

const item = $input.first().json || {};
const body = item.body || item;
let phone = body.phone || body.from || body.wa_id || '';
let text = pickText(body) || body.text || '';

const value = body.entry?.[0]?.changes?.[0]?.value
  || item.entry?.[0]?.changes?.[0]?.value;
if (value) {
  if (value.statuses && !value.messages) {
    return [];
  }
  const msg = (value.messages || [])[0] || {};
  phone = phone || msg.from || value.contacts?.[0]?.wa_id || '';
  text = text || pickText(msg);
}

if (body.messages?.[0]) {
  const msg = body.messages[0];
  phone = phone || msg.from || '';
  text = text || pickText(msg);
}

phone = String(phone || '').trim();
text = String(text || '').trim();
if (!phone) {
  return [];
}

return [{ json: { phone, text } }];

